import Foundation

/// Embedded test images, matching the Objective-C ImagePickerTestImages helper.
enum ImagePickerTestImages {
  static var jpgTestData: Data { data(resource: "jpgImage", ext: "jpg", fallback: jpgFallback) }
  static var jpgTallTestData: Data {
    data(resource: "jpgImageTall", ext: "jpg", fallback: jpgTallFallback)
  }
  static var pngTestData: Data { data(resource: "pngImage", ext: "png", fallback: pngFallback) }
  static var gifTestData: Data { data(resource: "gifImage", ext: "gif", fallback: gifFallback) }

  private static let jpgFallback =
    ""

  private static let jpgTallFallback =
    ""

  private static let pngFallback =
    ""

  private static let gifFallback =
    ""

  static var bundle: Bundle { Bundle(for: BundleToken.self) }

  private static func data(resource: String, ext: String, fallback: String) -> Data {
    if let url = bundle.url(forResource: resource, withExtension: ext),
      let loaded = try? Data(contentsOf: url), !loaded.isEmpty
    {
      return loaded
    }
    return Data(base64Encoded: fallback) ?? Data()
  }
}

final class BundleToken {}
